css:
.mob-sim-container { padding: 28px 24px; background: #f4f5f8; min-height: 100vh; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; color: #1a2744; }
.mob-sim-header { background: #1a2744; color: #ffffff; padding: 22px 28px; border-radius: 4px; margin-bottom: 18px; border-left: 5px solid #816a33; }
.mob-sim-header h1 { margin: 0; font-size: 1.45rem; font-weight: 600; letter-spacing: 0.02em; }
.mob-sim-eyebrow { margin-top: 8px; font-size: 0.72rem; color: #816a33; letter-spacing: 0.08em; text-transform: uppercase; }
.mob-sim-period-bar { display: flex; justify-content: space-between; align-items: center; background: #ffffff; padding: 12px 22px; border: 1px solid #e1e5eb; border-radius: 4px; margin-bottom: 18px; flex-wrap: wrap; gap: 10px; }
.mob-sim-period-counter { font-size: 0.9rem; color: #4a5876; }
.mob-sim-period-counter span#currentDay, .mob-sim-period-counter span#maxPeriods { font-weight: 700; color: #1a2744; }
.mob-sim-period-phase { display: inline-block; margin-left: 14px; padding: 3px 10px; background: #eef0f5; color: #1a2744; border-radius: 3px; font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase; font-weight: 600; }
.mob-sim-defensibility { font-size: 0.85rem; color: #4a5876; }
.mob-sim-defensibility strong { font-size: 1.15rem; color: #1a2744; margin-left: 8px; font-weight: 700; }
.mob-sim-briefing { background: #ffffff; padding: 22px 26px; border: 1px solid #e1e5eb; border-radius: 4px; border-top: 3px solid #816a33; margin-bottom: 18px; }
.mob-sim-briefing h2 { font-size: 1.05rem; margin: 0 0 8px 0; color: #1a2744; font-weight: 600; }
.mob-sim-segment-meta { margin-bottom: 14px; display: flex; gap: 8px; flex-wrap: wrap; }
.mob-sim-segment-pill { display: inline-block; padding: 4px 12px; background: #1a2744; color: #ffffff; border-radius: 3px; font-size: 0.74rem; letter-spacing: 0.06em; text-transform: uppercase; font-weight: 600; }
.mob-sim-roles-pill { display: inline-block; padding: 4px 12px; background: #c9a653; color: #1a2744; border-radius: 3px; font-size: 0.74rem; letter-spacing: 0.04em; font-weight: 700; }
.mob-sim-briefing p { margin: 0; line-height: 1.55; color: #2c3a55; font-size: 0.92rem; }
.mob-sim-status-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin-bottom: 18px; }
.mob-sim-status-card { background: #ffffff; padding: 14px 16px; border: 1px solid #e1e5eb; border-radius: 4px; border-left: 3px solid #1a2744; }
.mob-sim-status-card--trad { border-left-color: #2e5c8a; }
.mob-sim-status-card--rot { border-left-color: #5b8a5e; }
.mob-sim-status-card--hyb { border-left-color: #816a33; }
.mob-sim-status-card--risk { border-left-color: #b04848; }
.mob-sim-status-card--cost { border-left-color: #6b4a8a; }
.mob-sim-status-label { font-size: 0.7rem; color: #667183; letter-spacing: 0.06em; text-transform: uppercase; font-weight: 600; margin-bottom: 6px; }
.mob-sim-status-value { font-size: 1.5rem; font-weight: 700; color: #1a2744; line-height: 1.1; }
.mob-sim-controls { background: #ffffff; padding: 22px 26px; border: 1px solid #e1e5eb; border-radius: 4px; margin-bottom: 18px; }
.mob-sim-controls h3 { font-size: 0.78rem; color: #667183; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 600; margin: 0 0 16px 0; }
.mob-sim-allocation-panel { margin-bottom: 18px; padding-bottom: 18px; border-bottom: 1px solid #eef0f5; }
.mob-sim-allocation-hint { font-size: 0.82rem; color: #4a5876; margin: 0 0 12px 0; font-style: italic; }
.mob-sim-input-row { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; }
.mob-sim-input-group { display: flex; flex-direction: column; }
.mob-sim-input-group label { font-size: 0.78rem; font-weight: 600; color: #1a2744; margin-bottom: 6px; }
.mob-sim-input-group small { font-size: 0.7rem; color: #667183; margin-top: 4px; font-style: italic; }
.mob-sim-controls input[type="number"] { background: #ffffff; border: 1px solid #c8cfdc; color: #1a2744; border-radius: 3px; padding: 8px 12px; font-size: 0.95rem; width: 100%; }
.mob-sim-controls input[type="number"]:focus { outline: none; border-color: #816a33; box-shadow: 0 0 0 2px rgba(201,166,83,0.2); }
.mob-sim-governance-panel { margin-bottom: 18px; }
.mob-sim-governance-panel label { display: block; font-size: 0.78rem; font-weight: 600; color: #1a2744; margin-bottom: 6px; }
.mob-sim-controls select { background: #ffffff; border: 1px solid #c8cfdc; color: #1a2744; border-radius: 3px; padding: 8px 12px; font-size: 0.92rem; width: 100%; }
.mob-sim-controls select:focus { outline: none; border-color: #816a33; }
.mob-sim-controls select option { background: #ffffff; color: #1a2744; }
.mob-sim-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.mob-sim-controls .btn-primary { background: #1a2744; border-color: #1a2744; color: #ffffff; padding: 9px 22px; font-weight: 600; font-size: 0.9rem; letter-spacing: 0.04em; border-radius: 3px; transition: background 0.18s ease; }
.mob-sim-controls .btn-primary:hover { background: #2c3e6b; border-color: #2c3e6b; }
.mob-sim-controls .btn-outline-secondary { color: #4a5876; border-color: #c8cfdc; padding: 9px 16px; font-weight: 500; font-size: 0.85rem; border-radius: 3px; }
.mob-sim-feedback { background: #fdfaf2; border: 1px solid #ead9a8; border-left: 3px solid #816a33; padding: 14px 18px; border-radius: 3px; font-size: 0.88rem; color: #2c3a55; line-height: 1.5; margin-bottom: 18px; min-height: 20px; }
.mob-sim-feedback:empty { display: none; }
.mob-sim-history { background: #ffffff; padding: 18px 22px; border: 1px solid #e1e5eb; border-radius: 4px; margin-bottom: 18px; overflow-x: auto; }
.mob-sim-history h3 { font-size: 0.78rem; color: #667183; letter-spacing: 0.1em; text-transform: uppercase; font-weight: 600; margin: 0 0 12px 0; }
.mob-sim-history table { font-size: 0.82rem; color: #2c3a55; margin-bottom: 0; }
.mob-sim-history th { background: #1a2744; color: #ffffff; font-weight: 600; font-size: 0.7rem; letter-spacing: 0.06em; text-transform: uppercase; padding: 8px 10px; border: none; }
.mob-sim-history td { padding: 8px 10px; border-top: 1px solid #eef0f5; }
.mob-sim-chart { background: #ffffff; padding: 22px; border: 1px solid #e1e5eb; border-radius: 4px; height: 320px; position: relative; }
.mob-sim-chart canvas { max-height: 280px; }
@media (max-width: 768px) {
.mob-sim-container { padding: 16px 12px; }
.mob-sim-header { padding: 16px 18px; }
.mob-sim-header h1 { font-size: 1.15rem; }
.mob-sim-period-bar { flex-direction: column; align-items: flex-start; }
.mob-sim-status-value { font-size: 1.2rem; }
.mob-sim-input-row { grid-template-columns: 1fr; }
.mob-sim-actions { flex-direction: column; }
.mob-sim-actions .btn { width: 100%; }
}


/* --- EQIL 2026-08-08: accessibility --------------------------------------- */
:is(button, a, select, input, [tabindex]):focus-visible {
    outline: 3px solid #1f4e79;
    outline-offset: 2px;
    border-radius: 3px;
}
.mob-sim-complete {
    margin: 1.25rem 0;
    padding: 1.25rem 1.5rem;
    background: #ffffff;
    border: 1px solid #d0d7de;
    border-left: 6px solid #816a33;
    border-radius: 4px;
    color: #1f2937;
    white-space: pre-line;
    line-height: 1.6;
}
@media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        scroll-behavior: auto !important;
    }
}

