                }

                if (allocPenalty === 0) {
                    feedback += sim.t('fb_alloc_perfect') + '<br>';
                } else {
                    const tgt = sim.t('fb_alloc_target')
                        .replace('{t}', target.traditional)
                        .replace('{r}', target.rotational)
                        .replace('{h}', target.hybrid);
                    feedback += tgt + '<br>';
                }
            } else if (p.phase === 'B') {
                if (d.governance === p.bestGov) {
                    segmentScore = 100;
                    ds.cohortScore += 33;
                    feedback += sim.t('fb_cohort_good') + '<br>';
                } else if (p.fallbackGov && d.governance === p.fallbackGov) {
                    segmentScore = 60;
                    ds.cohortScore += 18;
                    feedback += sim.t('fb_cohort_partial') + '<br>';
                } else {
                    segmentScore = 25;
                    ds.cohortScore += 5;
                    feedback += sim.t('fb_cohort_weak') + '<br>';
                }
            } else if (p.phase === 'C') {
                if (d.governance === p.bestGov) {
                    segmentScore = 100;
                    ds.packScore += 34;
                    feedback += sim.t('fb_pack_good') + '<br>';
                } else if (p.fallbackGov && d.governance === p.fallbackGov) {
                    segmentScore = 55;
                    ds.packScore += 17;
                    feedback += sim.t('fb_pack_partial') + '<br>';
                } else {
                    segmentScore = 25;
                    ds.packScore += 4;
                    feedback += sim.t('fb_pack_weak') + '<br>';
                }
            }

            const placed = Math.max(1, ds.rolesPlaced);
            const tradPct = ds.portfolioTraditional / placed;
            let concentrationPenalty = 0;
            if (tradPct > 0.6) concentrationPenalty = Math.min(25, (tradPct - 0.6) * 100);
            const peRiskPenalty = ds.peRiskFlags * 4;
            ds.defensibility = Math.max(0, Math.round(100 - concentrationPenalty - peRiskPenalty));

            ds.scoreHistory.push(Math.round(segmentScore));
            ds.costHistory.push(parseFloat(costMultiple.toFixed(2)));
            ds.feedback = feedback;

            // Platform score = the summary composite of the running day average, taken from domainState.scoreHistory (the Open player keeps no state.history).
            const dayScores = ds.scoreHistory || [];
            const avgSegment = dayScores.reduce(function(s, v) { return s + (v || 0); }, 0) / Math.max(1, dayScores.length);
            const comp = this._composite(ds, avgSegment);
            const band = this._perfBand(comp.score, ds, comp.avg);
            const grade = this._letterGrade(comp.score);
            ds.overallScore = comp.score;
            ds.totalScore = comp.score;
            ds.score = comp.score;
            ds.composite = comp.score;
            ds.scoreCapped = comp.capped;
            ds.performanceBand = band;
            ds.grade = grade;
            // express_extractMetrics and express_extractHistory read
            // domainState.performance.overallScore and .grade for the instructor Score
            // column and the LTI grade passback. Written before the engine snapshots
            // domainState into history so every documented read path is populated.
            ds.performance = { overallScore: comp.score, grade: grade, band: band };

            const result = {
                period: period,
                overallScore: comp.score,
                totalScore: comp.score,
                score: comp.score,
                grade: grade,
                performance: band,
                segment: sim.t(p.segmentKey),
                phase: p.phase,
                segmentScore: Math.round(segmentScore),
                costMultiple: parseFloat(costMultiple.toFixed(2)),
                tradPlaced: d.traditional,
                rotPlaced: d.rotational,
                hybPlaced: d.hybrid,
                governanceLabel: this._labelForValue(p, d.governance),
                cumDefensibility: ds.defensibility
            };

            // The engine increments currentPeriod between here and the timer callback, so
            // the next day must be captured now. Reading state.currentPeriod inside the
            // callback advanced the view by two days.
            const nextPeriod = (period || 1) + 1;
            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: nextPeriod });
            }, 600);

            return result;
        }

        _labelForValue(period, value) {
            const sim = window.mySimulation;
            const opt = period.govOptions.find(function(o) { return o.value === value; });
            return opt ? sim.t(opt.labelKey) : value;
        }

