        getPerformanceSummary(history) {
            history = history || [];
            const sim = window.mySimulation;
            const ds = (sim && sim.state && sim.state.domainState) || {};
            const totalScore = history.reduce((s, r) => s + (r.results && r.results.segmentScore ? r.results.segmentScore : 0), 0);
            const days = ds.scoreHistory || [];
            // the Open player keeps no state.history: fall back to the day scores in domainState
            const avg = history.length ? (totalScore / history.length) : (days.length ? days.reduce(function(s, v) { return s + (v || 0); }, 0) / days.length : 0);
            const placed = Math.max(1, ds.rolesPlaced || 0);
            const tradPct = Math.round(((ds.portfolioTraditional || 0) / placed) * 100);
            const rotPct = Math.round(((ds.portfolioRotational || 0) / placed) * 100);
            const hybPct = Math.round(((ds.portfolioHybrid || 0) / placed) * 100);
            const avgCost = ((ds.totalCostMultiple || 0) / placed).toFixed(2);
            const comp = this._composite(ds, avg);
            const band = this._perfBand(comp.score, ds, comp.avg);

            const insights = [];
            if ((ds.peRiskFlags || 0) > 2) insights.push(this._t('insight_pe', ''));
            if (tradPct > 50) insights.push(this._t('insight_trad_heavy', ''));
            if ((ds.cohortScore || 0) < 50) insights.push(this._t('insight_cohort_weak', ''));
            if ((ds.packScore || 0) < 50) insights.push(this._t('insight_pack_weak', ''));
            if (band === 'distinguished') insights.push(this._t('insight_distinguished', ''));
            const clean = insights.filter(function(i) { return i; });

            return {
                averageScore: comp.avg,
                defensibility: comp.defensibility,
                cohortScore: Math.min(100, Math.round(ds.cohortScore || 0)),
                packScore: Math.min(100, Math.round(ds.packScore || 0)),
                portfolioSplit: tradPct + '% / ' + rotPct + '% / ' + hybPct + '%',
                avgCostMultiple: avgCost + 'x',
                peRiskFlags: ds.peRiskFlags || 0,
                composite: comp.score,
                overallScore: comp.score,
                totalScore: comp.score,
                score: comp.score,
                grade: this._letterGrade(comp.score),
                scoreCapped: this._t(comp.capped ? 'capped_yes' : 'capped_no'),
                performance: this._t('perf_' + band, band),
                performanceKey: 'perf_' + band,
                performanceLabel: this._t('perf_' + band, band),
                insights: clean.length ? clean : [this._t('insight_default', '')].filter(function(i) { return i; })
            };
        }

        getHint(state, results) {
            const sim = window.mySimulation;
            if (!results) return null;
            if (state.domainState.peRiskFlags >= 2 && state.currentPeriod <= 4) return sim.t('hint_pe_risk');
            const placed = Math.max(1, state.domainState.rolesPlaced);
            if ((state.domainState.portfolioTraditional / placed) > 0.6 && state.currentPeriod >= 3) return sim.t('hint_trad_heavy');
            if (results.segmentScore < 50) return sim.t('hint_low_score');
            if (state.currentPeriod === 4) return sim.t('hint_cohort_next');
            if (state.currentPeriod === 7) return sim.t('hint_pack_next');
            return null;
        }

